-- Market Place Data (Google Drive) -> Supabase.
-- Generated by: python -m mp.pipeline --print-schema
-- Run this whole file in the Supabase SQL editor. Safe to re-run.
--
-- Folder order follows the numbered Drive folders:
--   1) Discount Split  2) Off Invoice Split  3) Ads Split  4) Ads Raw
-- The 'Not to be uploaded in Supabase' folder is never read.

create table if not exists public.workflow_logs (
    id               bigint generated always as identity primary key,
    source           text,
    workflow         text        not null,
    started_at       timestamptz not null,
    ended_at         timestamptz not null,
    duration_seconds numeric,
    status           text,
    files_seen       integer,
    files_loaded     integer,
    files_skipped    integer,
    rows_written     integer,
    details          jsonb,
    created_at       timestamptz not null default now()
);

create index if not exists workflow_logs_started_at_idx
    on public.workflow_logs (started_at desc);

-- workflow_logs is shared with the GRN schedulers and already exists there with
-- a narrower column set, so `create table if not exists` above is a no-op and
-- these columns have to be added explicitly. Without them every run logs
-- PGRST204 "Could not find the 'files_loaded' column".
alter table public.workflow_logs add column if not exists source text;
alter table public.workflow_logs add column if not exists files_seen integer;
alter table public.workflow_logs add column if not exists files_loaded integer;
alter table public.workflow_logs add column if not exists files_skipped integer;
alter table public.workflow_logs add column if not exists rows_written integer;
alter table public.workflow_logs add column if not exists duration_seconds numeric;
alter table public.workflow_logs add column if not exists status text;
alter table public.workflow_logs add column if not exists details jsonb;

create table if not exists public.mp_loaded_files (
    id            bigint generated always as identity primary key,
    source_key    text        not null,
    table_name    text        not null,
    drive_file_id text        not null,
    source_file   text        not null,
    rows_written  integer,
    loaded_at     timestamptz not null default now(),
    unique (table_name, drive_file_id)
);

create index if not exists mp_loaded_files_table_idx
    on public.mp_loaded_files (table_name);

comment on table public.mp_loaded_files is
    'One row per fully-loaded source file. Written only after every batch of
     that file succeeded, so an interrupted run resumes without gaps.';

-- mp_discount_split
--   1 ALL | Discount / Offers split
--     Drive: 1) Discount Split Data/Discounting Data [sheet: Discount Data]
--     Offers/discount spend per SKU per month per platform. Some months
--     carry a blank leading row, so the header row is auto-detected.
create table if not exists public.mp_discount_split (
    id                bigint generated always as identity primary key,
    row_hash          text        not null unique,
    source_file       text,
    drive_file_id     text,
    source_path       text,
    platform          text,
    date_grain        text,
    report_date       date,
    category          text,
    discount_amount   numeric,
    item_id           text,
    month             date,
    sku_name          text,
    processed_at      timestamptz not null default now(),
    raw_data          jsonb,
    created_at        timestamptz not null default now()
);

alter table public.mp_discount_split
    add column if not exists source_file_lower text
    generated always as (lower(source_file)) stored;

-- Column evolution: no-ops on a fresh table, and the reason re-running
-- this file picks up columns discovered after it was first applied.
alter table public.mp_discount_split add column if not exists source_file text;
alter table public.mp_discount_split add column if not exists drive_file_id text;
alter table public.mp_discount_split add column if not exists source_path text;
alter table public.mp_discount_split add column if not exists platform text;
alter table public.mp_discount_split add column if not exists date_grain text;
alter table public.mp_discount_split add column if not exists report_date date;
alter table public.mp_discount_split add column if not exists category text;
alter table public.mp_discount_split add column if not exists discount_amount numeric;
alter table public.mp_discount_split add column if not exists item_id text;
alter table public.mp_discount_split add column if not exists month date;
alter table public.mp_discount_split add column if not exists sku_name text;

comment on column public.mp_discount_split.row_hash is
    'sha256 of the typed row; makes re-runs idempotent via upsert';
comment on column public.mp_discount_split.raw_data is
    'overflow only: columns this table has no typed column for. NULL when there are none';

create index if not exists mp_discount_split_source_file_lower_idx on public.mp_discount_split (source_file_lower);
create index if not exists mp_discount_split_report_date_idx on public.mp_discount_split (report_date);
create index if not exists mp_discount_split_platform_idx on public.mp_discount_split (platform);

-- No GIN index on raw_data by design. It is the single most expensive index
-- available here, and raw_data is now overflow-only and usually NULL, so it
-- would cost storage to index almost nothing. If a column does start
-- arriving in raw_data and needs querying, prefer promoting it to a typed
-- column (re-run --discover). Add the index only if you really need it:
--   create index mp_discount_split_raw_data_idx on public.mp_discount_split using gin (raw_data);

