-- No GIN index on raw_data by design. It is the single most expensive index
-- available here, and raw_data is now overflow-only and usually NULL, so it
-- would cost storage to index almost nothing. If a column does start
-- arriving in raw_data and needs querying, prefer promoting it to a typed
-- column (re-run --discover). Add the index only if you really need it:
--   create index instamart_ads_performance_raw_data_idx on public.instamart_ads_performance using gin (raw_data);

-- zepto_campaign_performance
--   4.6 ZEPTO | Campaign performance
--     Drive: 4) Ads Raw Data/Zepto/Zepto Visibility Data [sheet: Sheet1]
--     ~1073 one-day workbooks with no date column; the file name
--     (19-Jan-26.xlsx) is the report date.
create table if not exists public.zepto_campaign_performance (
    id                bigint generated always as identity primary key,
    row_hash          text        not null unique,
    source_file                  text,
    drive_file_id                text,
    source_path                  text,
    platform                     text,
    date_grain                   text,
    report_date                  date,
    atc                          numeric,
    brandid                      text,
    brandname                    text,
    campaign_id                  text,
    campaign_name                text,
    campaignname                 text,
    campaigntype                 text,
    clicks                       numeric,
    cpc                          numeric,
    cpm                          numeric,
    ctr                          numeric,
    daily_budget                 numeric,
    date                         date,
    impressions                  numeric,
    keywordmatchtype             text,
    keywordname                  text,
    new_to_brand_user_percentage numeric,
    orders                       numeric,
    other_skus                   numeric,
    revenue                      numeric,
    roas                         numeric,
    robas                        numeric,
    same_skus                    numeric,
    spend                        numeric,
    status                       text,
    unique_considerations        numeric,
    unique_reach                 numeric,
    processed_at      timestamptz not null default now(),
    raw_data          jsonb,
    created_at        timestamptz not null default now()
);

alter table public.zepto_campaign_performance
    add column if not exists source_file_lower text
    generated always as (lower(source_file)) stored;

-- Column evolution: no-ops on a fresh table, and the reason re-running
-- this file picks up columns discovered after it was first applied.
